// spec: specs/client-ordering.md §9 · кейсы co-29, co-30 (.qa/tests/client-ordering/) — «הזמן שוב» в деталях заказа клиента
// #aef12a (ff0bd29eadd9e87f15aef12a, commits 924a67b, b20016d, f6a68e4; прошёл ручную QA 18.10, «הושלם»).
// Тесты «כפתור» только смотрят (@prod-safe, кнопку не нажимают).
// Тесты @data: admin создаёт товары «QA-AUTO-client-ordering-aef1-<ts>-A/B/C/D», buyer оформляет 2 заказа, admin меняет
//   цену A, выключает «זמינות» B, удаляет D (архив); затем «הזמן שוב». Корзина buyer снимается до и восстанавливается после
//   (_cart-snapshot.ts); заказы отклоняются, товары удаляются (afterAll).
// ⚠️ @data-тесты НЕ запускать параллельно с другими тестами корзины buyer (cart-checkout, cart-remove-no-flash,
//    recent-products @data, orders/order-lifecycle, inventory/inventory-lifecycle, picking/picking-flow,
//    customers-pricing/pricing-lifecycle …) — общая корзина.
// Только вручную: количество больше остатка / меньше нового минимума (пометка строки), bidi латиницы в сообщении (визуально).
import { test, expect, Page, Browser } from '@playwright/test';
import { auth, createStockedProduct, deleteProduct, findProduct, placeOrder, cleanup } from '../orders/_qa-order';
import { cartSnapshot, restoreCartIn, CartLine } from './_cart-snapshot';

test.use({ storageState: auth('buyer') });

const REORDER = 'הזמן שוב';
const summary = (page: Page) => page.getByText('סה״כ משוער').locator('..');

type Order = { id: string; order_no: number; status: string; shipping_status: string | null; created_at: string };

async function ordersApi(page: Page) {
  const resp = page.waitForResponse((r) => {
    const u = decodeURIComponent(r.url());
    return u.includes('/rest/v1/orders?select=') && u.includes('order_items(') && r.request().method() === 'GET';
  }, { timeout: 30_000 });
  await page.goto('/shop/orders');
  return (await (await resp).json()) as Order[];
}

/** Кнопка «הזמן שוב» видна без прокрутки и не перекрыта таббаром. */
async function expectReorderAtBottom(page: Page) {
  const btn = page.getByRole('button', { name: REORDER });
  await expect(btn).toBeVisible({ timeout: 20_000 });
  await expect(btn).toBeEnabled();
  await expect(btn).toBeInViewport({ ratio: 1 });
  const box = (await btn.boundingBox())!;
  const vh = page.viewportSize()!.height;
  expect(box.y + box.height).toBeLessThanOrEqual(vh);
  expect(box.y, 'кнопка в нижней половине экрана').toBeGreaterThan(vh / 2);
  const navTop = await page.evaluate(() => {
    const nav = [...document.querySelectorAll('nav')].find((n) => /קטלוג/.test(n.textContent || '') && /הזמנות/.test(n.textContent || ''));
    return nav ? nav.getBoundingClientRect().top : null;
  });
  if (navTop !== null) expect(box.y + box.height, 'кнопка над таббаром «קטלוג / עגלה / הזמנות»').toBeLessThanOrEqual(navTop + 0.5);
}

test.describe('client-ordering — «הזמן שוב»: כפתור בפרטי ההזמנה', () => {
  test('כפתור «הזמן שוב» בתחתית הפרטים של הזמנה מכל סטטוס #aef12a @desktop @prod-safe', async ({ page }) => {
    const orders = await ordersApi(page);
    expect(orders.length, 'у buyer есть заказы').toBeGreaterThan(0);
    const byStatus = new Map<string, Order>();
    for (const o of orders) {
      const k = `${o.status}/${o.shipping_status ?? ''}`;
      if (!byStatus.has(k)) byStatus.set(k, o);
    }
    test.info().annotations.push({ type: '#aef12a', description: `статусы: ${[...byStatus.keys()].join(', ')}` });
    for (const o of [...byStatus.values()].slice(0, 6)) {
      await page.goto(`/shop/order/${o.id}`);
      await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${o.order_no}` })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByRole('heading', { name: 'פריטים' })).toBeVisible();
      await expect(page.getByText('סה״כ', { exact: true })).toBeVisible();
      await expectReorderAtBottom(page);
    }
  });

  test('טלפון: «הזמן שוב» גלוי, בתחתית, לא מוסתר ע״י סרגל הלשוניות #aef12a @iphone @prod-safe', async ({ page }) => {
    const [o] = await ordersApi(page);
    test.skip(!o, 'нет заказов');
    await page.goto(`/shop/order/${o.id}`);
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${o.order_no}` })).toBeVisible({ timeout: 20_000 });
    await expectReorderAtBottom(page);
    const [sw, cw] = await page.evaluate(() => [document.documentElement.scrollWidth, document.documentElement.clientWidth]);
    expect(sw, 'без горизонтальной прокрутки').toBeLessThanOrEqual(cw);
  });
});

test.describe('client-ordering — «הזמן שוב»: הוספה לעגלה (@data, корзина buyer)', () => {
  test.describe.configure({ mode: 'serial' });
  const TS = Date.now().toString().slice(-7);
  const mk = (l: string, price: number) => ({ name: `QA-AUTO-client-ordering-aef1-${TS}-${l}`, sku: `QACOAEF1${TS}${l}`, price, id: '' });
  const A = mk('A', 3), B = mk('B', 4), C = mk('C', 2), D = mk('D', 2);
  let snap: CartLine[] | undefined;
  let N1 = '', N2 = ''; // заказ 1: A×2, B, C, D; заказ 2: только B

  async function adminDo(browser: Browser, fn: (ap: Page) => Promise<void>) {
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    try { await fn(await ctx.newPage()); } finally { await ctx.close(); }
  }

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(480_000);
    await adminDo(browser, async (ap) => {
      for (const p of [A, B, C, D]) p.id = await createStockedProduct(ap, p.name, p.sku, p.price, 10);
    });
    const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    const bp = await ctx.newPage();
    snap = await cartSnapshot(bp);
    N1 = await placeOrder(bp, [{ ...A, qty: 2 }, { ...B, qty: 1 }, { ...C, qty: 1 }, { ...D, qty: 1 }], `QA-AUTO-client-ordering-aef1-${TS}-o1`);
    N2 = await placeOrder(bp, [{ ...B, qty: 1 }], `QA-AUTO-client-ordering-aef1-${TS}-o2`);
    await ctx.close();
    // после заказов: цена A 3 → 5, B недоступен, D удалён (архив)
    await adminDo(browser, async (ap) => {
      await ap.goto(`/catalog/${A.id}/edit`);
      const price = ap.getByRole('spinbutton', { name: 'מחיר בסיס' });
      await expect(price).toHaveValue('3', { timeout: 20_000 });
      await price.fill('5');
      await ap.getByRole('button', { name: 'שמירה', exact: true }).click();
      await expect(ap.getByText(/עודכן\.$/).first()).toBeVisible({ timeout: 15_000 });

      expect(await findProduct(ap, B.name)).toBe(true);
      const sw = ap.getByRole('switch', { name: `זמינות ${B.name}` });
      await expect(sw).toHaveAttribute('aria-checked', 'true', { timeout: 20_000 });
      await sw.click();
      await expect(sw).toHaveAttribute('aria-checked', 'false');

      await deleteProduct(ap, D.name);
    });
  });

  test.afterAll(async ({ browser }) => {
    test.setTimeout(300_000);
    await restoreCartIn(browser, snap);
    await cleanup(browser, [N1, N2], [A.name, B.name, C.name, D.name]);
  });

  test.skip('«הזמן שוב»: כל המוצרים הזמינים לעגלה באותן כמויות בנוסף לקיים, במחיר העדכני; לא זמין/נמחק — לא נוסף והודעה בשמו; אין שליחה אוטומטית; ההודעה לא חוזרת אחרי רענון #aef12a @desktop @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    test.setTimeout(180_000);
    // корзина: уже лежит A×1 (A — текущая цена ₪5)
    await page.goto(`/shop/p/${A.id}`);
    const added = page.waitForResponse((r) => r.url().includes('cart_set_item'));
    await page.getByRole('button', { name: /^הוסף לעגלה/ }).click();
    await added;
    await page.goto('/shop/cart');
    await expect(page.getByRole('button', { name: `הסרה מהעגלה — ${A.name}` })).toBeVisible({ timeout: 20_000 });
    await expect(summary(page)).toContainText('₪5.00');

    // детали заказа 1 — старые цены (D-13)
    await page.goto('/shop/orders');
    await page.getByRole('link', { name: new RegExp(`^הזמנה #${N1}\\b`) }).click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${N1}` })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('2 × ₪3.00')).toBeVisible();

    await page.getByRole('button', { name: REORDER }).click();
    await expect(page).toHaveURL(/\/shop\/cart/, { timeout: 20_000 });
    await expect(page.getByText(new RegExp(`המוצרים מהזמנה #${N1} נוספו לעגלה \\(2 פריטים\\)`)).first()).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText(/המחירים מעודכנים להיום/).first()).toBeVisible();
    await expect(page.getByText(new RegExp(`לא זמינים כעת ולא נוספו:.*${B.name}`)).first()).toBeVisible();
    await expect(page.getByText(new RegExp(`כבר לא בקטלוג ולא נוספו:.*${D.name}`)).first()).toBeVisible();

    // A: 1 (было) + 2 (из заказа) = 3 × ₪5; C: 1 × ₪2; B и D нет → ₪17.00
    await expect(page.getByRole('button', { name: `הסרה מהעגלה — ${A.name}` })).toHaveCount(1);
    await expect(page.getByRole('button', { name: `הסרה מהעגלה — ${C.name}` })).toHaveCount(1);
    await expect(page.getByRole('button', { name: `הסרה מהעגלה — ${B.name}` })).toHaveCount(0);
    await expect(page.getByRole('button', { name: `הסרה מהעגלה — ${D.name}` })).toHaveCount(0);
    await expect(summary(page)).toContainText('₪17.00', { timeout: 15_000 });
    const lines = new Map((await cartSnapshot(page)).map((l) => [l.product_id, l.qty]));
    expect(lines.get(A.id), 'A: 1 в корзине + 2 из заказа').toBe(3);
    expect(lines.get(C.id)).toBe(1);

    // F5 — сообщение не возвращается (f6a68e4); правка перед отправкой — удалить C → ₪15.00
    await page.reload();
    await expect(page.getByRole('button', { name: `הסרה מהעגלה — ${C.name}` })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText(/נוספו לעגלה/)).toHaveCount(0);
    await expect(page.getByText(/לא זמינים כעת ולא נוספו/)).toHaveCount(0);
    await page.getByRole('button', { name: `הסרה מהעגלה — ${C.name}` }).click();
    await expect(page.getByRole('button', { name: `הסרה מהעגלה — ${C.name}` })).toHaveCount(0, { timeout: 15_000 });
    await expect(summary(page)).toContainText('₪15.00');
    await expect(page.getByRole('button', { name: 'המשך לביצוע הזמנה' })).toBeEnabled();

    // заказ сам не отправлен: верхний заказ — по-прежнему N2
    await page.goto('/shop/orders');
    await expect(page.getByRole('link', { name: /^הזמנה #\d+/ }).first()).toContainText(`#${N2}`, { timeout: 20_000 });
  });

  test.skip('«הזמן שוב» כשאף מוצר לא זמין — הודעה במסך ההזמנה, בלי מעבר לעגלה, העגלה לא משתנה #aef12a @desktop @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    const before = await cartSnapshot(page);
    await page.goto('/shop/orders');
    await page.getByRole('link', { name: new RegExp(`^הזמנה #${N2}\\b`) }).click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${N2}` })).toBeVisible({ timeout: 20_000 });
    await page.getByRole('button', { name: REORDER }).click();
    await expect(page.getByText(new RegExp(`אף אחד מהמוצרים בהזמנה הזו אינו זמין כעת להזמנה:.*${B.name}`)).first()).toBeVisible({ timeout: 20_000 });
    await expect(page).toHaveURL(/\/shop\/order\/[0-9a-f-]{36}/);
    const after = await cartSnapshot(page);
    const norm = (c: CartLine[]) => c.map((l) => `${l.product_id}:${l.qty}`).sort();
    expect(norm(after), 'корзина не изменилась').toEqual(norm(before));
  });
});
